import{_ as a,o,c as t,a2 as n}from"./chunks/framework.ei62kzQy.js";const p=JSON.parse('{"title":"Translations","description":"","frontmatter":{},"headers":[],"relativePath":"i18n/README.md","filePath":"i18n/README.md"}'),s={name:"i18n/README.md"};function r(l,e,d,i,c,g){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="translations" tabindex="-1">Translations <a class="header-anchor" href="#translations" aria-label="Permalink to &quot;Translations&quot;">​</a></h1><p>Every word a person reads lives here, one JSON file per language and namespace (<a href="./../docs/adr/0014-text-lives-in-one-json-file-per-language-and-namespace">ADR 0014</a>, <a href="./../docs/adr/0015-catalog-text-lives-in-translation-files">ADR 0015</a>). English in <code>messages/en/</code> is the source.</p><ul><li><a href="https://github.com/tkint/coach-poulpy/tree/main/i18n/messages" target="_blank" rel="noreferrer"><code>messages/&lt;locale&gt;/&lt;namespace&gt;.json</code></a>: the messages, nested JSON whose path is the message id, in ICU MessageFormat.</li><li><code>project.inlang/settings.json</code>: the inlang project that <a href="https://fink.inlang.com/" target="_blank" rel="noreferrer">Fink</a> reads, through the next-intl plugin.</li><li><code>glossary/&lt;locale&gt;.md</code>: rules and vocabulary per language (<a href="./glossary/en">English</a>, <a href="./glossary/fr">français</a>); the English one also holds the translator notes.</li><li><code>typography.mjs</code>: fixes apostrophes, ellipses and each language’s non-breaking spaces; it runs on <code>main</code> after every merge.</li></ul><h2 id="add-or-change-a-string" tabindex="-1">Add or change a string <a class="header-anchor" href="#add-or-change-a-string" aria-label="Permalink to &quot;Add or change a string&quot;">​</a></h2><ol><li>Add the message to <code>messages/en/&lt;namespace&gt;.json</code> and <code>messages/fr/&lt;namespace&gt;.json</code>, under the group of its screen or area: <code>app</code> for Android and iOS screens, <code>domain</code> for the words the shared Kotlin gives both apps, <code>catalog</code> for exercise text. Ids are <code>&lt;group&gt;.&lt;camelCaseName&gt;</code>; arguments are <code>{name}</code> for text, <code>{count, number}</code> for a whole number and <code>{count, plural, one {# step} other {# steps}}</code> for plurals.</li><li>Read it where it&#39;s used. The build generates everything else, nothing generated is committed, and it fails when a shipped language lacks the message or names other arguments: <ul><li><strong>Android</strong>: <code>R.string.&lt;id with dots as underscores&gt;</code> (<code>home.seeWorkout</code> is <code>R.string.home_seeWorkout</code>), or <code>R.plurals.…</code> for a plural, with arguments in order of first appearance in English.</li><li><strong>iOS</strong>: the id followed by one format per argument, in the same order: <code>Text(&quot;plan.title \\(name)&quot;)</code> reads <code>plan.title %@</code>, <code>L(&quot;player.step %lld %lld&quot;, index, count)</code> reads <code>player.step %lld %lld</code>.</li><li><strong>Shared Kotlin</strong>: <code>DomainText.&lt;id in camelCase&gt;(language, …)</code>, for example <code>DomainText.countRounds(languageCode, 3)</code>. <code>Labels</code> and <code>PoulpyCoach</code> wrap these for the view models.</li><li><strong>Catalog</strong>: <code>&lt;slug&gt;.name</code>, <code>&lt;slug&gt;.instructions.&lt;n&gt;</code>, <code>&lt;slug&gt;.variationNote</code> and the optional, comma-separated <code>&lt;slug&gt;.aliases</code>. Changing them raises the catalog <code>version</code>; CI fails a pull request that changes them without.</li></ul></li><li>A message translators could misread gets a note in <a href="./glossary/en">the English rules and notes</a>, never in the JSON.</li></ol><p>On the phones a plural can only branch on its language&#39;s forms (<code>one</code>, <code>many</code>, <code>other</code>…); an exact branch like <code>=0</code> works in <code>domain</code> only.</p><h2 id="proofread-or-translate-in-fink" tabindex="-1">Proofread or translate in Fink <a class="header-anchor" href="#proofread-or-translate-in-fink" aria-label="Permalink to &quot;Proofread or translate in Fink&quot;">​</a></h2><ol><li>Open <a href="https://fink.inlang.com/" target="_blank" rel="noreferrer">Fink</a> and sign in with a free GitHub account.</li><li>Open the repository <code>tkint/coach-poulpy</code>; Fink finds <code>i18n/project.inlang</code>.</li><li>Pick the language, edit, and send the changes: Fink opens a pull request.</li></ol><p>Read the <a href="./glossary/en">English rules and notes</a> and the glossary of your language (<a href="./glossary/fr">français</a>) first. Type plain apostrophes and spaces: the repository fixes the typography after each merge.</p><h2 id="add-a-language" tabindex="-1">Add a language <a class="header-anchor" href="#add-a-language" aria-label="Permalink to &quot;Add a language&quot;">​</a></h2><p>Add its folder under <code>messages/</code> with the three files, its locale to <code>locales</code> in <code>project.inlang/settings.json</code>, and <code>glossary/&lt;locale&gt;.md</code>.</p>',11)])])}const u=a(s,[["render",r]]);export{p as __pageData,u as default};
